class Solution {
public:
    NestedInteger deserialize(string s) {
        if (s[0] != '[') {
            return NestedInteger(stoi(s));
        }
        stack<NestedInteger> st;
        string num;
        for (char c : s) {
            if (c == '[') {
                st.push(NestedInteger());
            } else if (c == ',' || c == ']') {
                if (!num.empty()) {
                    st.top().add(NestedInteger(stoi(num)));
                    num.clear();
                }
                if (c == ']') {
                    NestedInteger top = st.top();
                    st.pop();
                    if (st.empty()) {
                        return top;
                    }
                    st.top().add(top);
                }
            } else {
                num.push_back(c);
            }
        }
        return NestedInteger();
    }
};
